# 1. TANTOYUCA (Naranja)
LAYER
    NAME "cz_01_tantoyuca"
    STATUS ON
    TYPE POLYGON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
    DATA "the_geom FROM coordinaciones.cz_01_tantoyuca USING UNIQUE gid USING SRID=900913"
    METADATA
        "wms_title" "CZ 01 Tantoyuca"
        "wms_enable_request" "*"
    END
    CLASS
        NAME "Tantoyuca"
        STYLE
            COLOR 235 151 78
            OUTLINECOLOR 60 60 60
            WIDTH 0.8
        END
    END
END

